function readStorageState(port: number): Promise<StorageState> {
  if (!Number.isInteger(port) || port < 1) throw new Error("JI_STAGE1_SESSION_PORT is required")
  return new Promise((resolve, reject) => {
    const socket = connect({ host: "127.0.0.1", port })
    let buffer = Buffer.alloc(0)
    socket.on("data", chunk => {
      buffer = Buffer.concat([buffer, chunk])
      if (buffer.length < 4) return
      const length = buffer.readUInt32BE(0)
      if (length < 2 || length > 16_384) {
        buffer.fill(0)
        socket.destroy()
        reject(new Error("invalid local authentication frame length"))
        return
      }
      if (buffer.length < 4 + length) return
      try {
        resolve(JSON.parse(buffer.subarray(4, 4 + length).toString("utf8")) as StorageState)
      } catch {
        reject(new Error("invalid local authentication state"))
      } finally {
        buffer.fill(0)
        socket.destroy()
      }
    })
    socket.once("error", reject)
    socket.once("close", hadError => {
      if (!hadError && buffer.length > 0 && buffer.length < 4) reject(new Error("truncated local authentication frame"))
    })
  })
}
